// color palette

let colors = ['#f0101c', '#ffffff','#f05697', '#0b469b', '#32b6c3', '#f78000', '#fddf0e', '#9fe063', '#315423', '#16141b','#ffffff'];

// scale of the vector field 
// smaller values => bigger structures  
// bigger values  ==> smaller structures 

var myScale = -2.1;

//var border = -100;

let agent = [];

let mySize;

function setup() {
  createCanvas(1000,1000);
  colorMode(HSB, 360, 100, 100,100);
  //strokeCap(SQUARE);
  background(90);
	//frameRate(60);

	mySize = 50;

	for(let xx=0; xx < width + mySize;xx+=(Math.max(0.001, Math.abs(mySize)) || 1))
	{
		for(let yy=0; yy < height + mySize;yy+=(Math.max(0.001, Math.abs(mySize)) || 1))
		{
			agent.push(new Agent(xx,yy));
		}
	}


	//randomSeed(1966);

}

function draw() {


  for(let i=0;i < agent.length;i++)
  {
    agent[i].update();
  }


}


// paintining agent 

class Agent {
  constructor(x,y)
  {

		this.p = createVector(x,y);


		this.directionX = 1;
		this.directionY = 1;

    this.pOld  = createVector(this.p.x,this.p.y);

    this.step  = 20;

    this.color = generateColor(10);


    this.strokeWidth = 40;
  }

  update() {

		if (this.strokeWidth > 0)
		{
		  this.strokeWidth -= 0.25;
		}

		this.p.x += this.directionX*vector_field(this.p.x,this.p.y).x*this.step;
    this.p.y += this.directionY*vector_field(this.p.x,this.p.y).y*this.step;


    strokeWeight(this.strokeWidth);

		stroke(this.color);

		addBlur(this.strokeWidth);
    line(this.pOld.x,this.pOld.y,this.p.x,this.p.y);

    this.pOld.set(this.p);

  }

}

// vector field function 
// the painting agents follow the flow defined 
// by this function 


function vector_field(x,y) {

  x = map(x,0,width,0,myScale);
  y = map(y,0,height,0,myScale);

  let k1 = 5;
  let k2 = 3;

  let u = sin(k1*y) + cos(k2*x);
  let v = sin(k2*x) - sin(k1*x);

	if (y > 0)
	{
	  if (v > 0)
	  {
      v = -v;
	  }
	}


  return createVector(u,v);
}

function addBlur(mySize)
{
	drawingContext.shadowOffsetX = -mySize*0.01;
  drawingContext.shadowOffsetY = 0;
  drawingContext.shadowBlur = mySize/4;
  drawingContext.shadowColor = 'black';
}

function generateColor(scale) {
	let temp = color(colors[floor(random(0,5))]);
	myColor = color(hue(window.color(temp)) + randomGaussian() * scale,
		saturation(window.color(temp)) + randomGaussian() * scale,
		brightness(window.color(temp)) + randomGaussian() * scale,
		random(99,100));
	return myColor;
}
